def stop(message: str):
    raise SystemExit('STOP: ' + message)


def running(pid: int) -> bool:
    try: os.kill(pid, 0); return True
    except ProcessLookupError: return False


def main():
    root = Path(__file__).resolve().parent
    if not (root/'backend/market_lab/api.py').is_file() or not (root/'frontend/package.json').is_file():
        stop('Copy this file into the RB-ITOS-AI repository root and run it there')
    python = root/'.venv/bin/python'
    if not python.is_file(): stop('Virtual environment missing: .venv/bin/python')
    pidfile = root/'data/runtime/api.json'
    if not pidfile.is_file(): stop('Managed API pid file missing; no process will be restarted')
    try:
        info=json.loads(pidfile.read_text())
        pid=int(info['pid'])
        if info.get('service')!='api' or Path(info['project_root']).resolve()!=root:
            stop('API pid file identifies another service or project')
        cmd=(Path(f'/proc/{pid}/cmdline').read_bytes()).replace(b'\0',b' ')
        if b'market_lab.runtime api' not in cmd: stop('API PID command does not match managed API')
        old_environment=Path(f'/proc/{pid}/environ').read_bytes()
        env=dict(item.decode('utf-8','surrogateescape').split('=',1) for item in old_environment.split(b'\0') if b'=' in item)
    except (KeyError, ValueError, OSError, UnicodeError) as exc:
        stop('Could not safely identify API or preserve its environment: '+str(exc))
    desired=[]
    for rel, expected in BASELINE.items():
        target=root/rel
        if not target.is_file(): stop('Missing source file: '+rel)
        new=base64.b85decode(PAYLOAD[rel])
        current=hashlib.sha256(target.read_bytes()).hexdigest()
        if current==hashlib.sha256(new).hexdigest(): continue
        backup=target.with_name(target.name+'.pre-live-ui-perf.bak')
        if rel=='frontend/src/App.tsx' and current==PREVIOUS_APP_SHA256:
            if not backup.is_file() or hashlib.sha256(backup.read_bytes()).hexdigest()!=expected:
                stop('Previous App backup missing or differs from uploaded baseline')
            desired.append((target, None, new))
            continue
        if current!=expected: stop('Source differs from reviewed ZIP: '+rel)
        if backup.exists(): stop('Backup already exists: '+str(backup))
        desired.append((target, backup, new))
    for target, backup, new in desired:
        if backup is not None: shutil.copy2(target, backup)
        target.write_bytes(new)
    print('Applied',len(desired),'source files; workers untouched.', flush=True)
    commands=[([str(python),'-m','pytest','-q','tests/test_storage_api.py'],root),
              (['npm','run','build'],root/'frontend'),
              (['git','diff','--check'],root)]
    for command, cwd in commands:
        print('Running:', ' '.join(command), flush=True)
        try: rc=subprocess.run(command,cwd=cwd,check=False).returncode
        except OSError as exc: stop('Could not run '+command[0]+': '+str(exc)+'; API unchanged')
        if rc: stop('Validation failed (exit '+str(rc)+'); API unchanged')
    # Repeat identity validation after a potentially long build.
    if not running(pid) or b'market_lab.runtime api' not in Path(f'/proc/{pid}/cmdline').read_bytes().replace(b'\0',b' '):
        stop('API identity changed during build; no process signaled')
    shadow_file=root/'data/live-shadow-worker.pid'
    shadow_before=shadow_file.read_text().strip() if shadow_file.exists() else 'unmanaged/unknown'
    print('Stopping only managed API PID',pid,flush=True)
    os.kill(pid,signal.SIGTERM)
    deadline=time.monotonic()+10
    while running(pid) and time.monotonic()<deadline: time.sleep(.2)
    if running(pid): stop('API did not stop gracefully; worker untouched')
    logs=root/'data/logs'; logs.mkdir(parents=True,exist_ok=True)
    with (logs/'api.log').open('ab') as stdout, (logs/'api-error.log').open('ab') as stderr:
        process=subprocess.Popen([str(python),'-m','market_lab.runtime','api'],cwd=root,env=env,
                                 stdout=stdout,stderr=stderr,stdin=subprocess.DEVNULL,start_new_session=True)
    deadline=time.monotonic()+12
    healthy=False
    while time.monotonic()<deadline:
        if process.poll() is not None: break
        try:
            with urlopen('http://127.0.0.1:8123/api/health',timeout=1) as response:
                healthy=response.status==200
            if healthy: break
        except Exception: time.sleep(.25)
    shadow_after=shadow_file.read_text().strip() if shadow_file.exists() else 'unmanaged/unknown'
    if not healthy: stop('API health failed; inspect data/logs/api-error.log; worker untouched')
    print('API healthy; live-shadow worker PID before:',shadow_before,'after:',shadow_after)
    if shadow_before!=shadow_after: stop('Worker PID changed externally during run; investigate')
    with urlopen('http://127.0.0.1:8123/api/state?history_limit=1',timeout=10) as response:
        body=json.loads(response.read())
    print('Slim state observations:',len(body.get('history',[])), 'total recorded:',body.get('observation_count'))
    print('Done. In Chrome, uncheck Disable cache, close DevTools, then refresh.')

if __name__=='__main__': main()
